// FONDA — entrée d'émission : { set_id, journal_commit, referentiel_version, moteur } (CLI d'Éric, après diagnostic « généré »).
// GÉNÉRÉ par n8n/fonda-relecture-page/construire-relecture.js : ne pas éditer dans
// l'interface (le harnais compare ce code, octet pour octet, à celui du dépôt).

const SET_ID_PATTERN = new RegExp("^set_fonda_[a-z0-9-]+_n[IF]_\\d{2}$", "");

function unItem(nom) {
  const items = nom === null ? $input.all() : $(nom).all();
  if (!Array.isArray(items) || items.length !== 1 || !items[0] || typeof items[0].json !== 'object' || items[0].json === null) {
    throw new Error('FONDA Entree emission : exactement un item attendu de ' + (nom === null ? 'l\'entrée' : nom));
  }
  return items[0].json;
}

const b = unItem(null).body;
if (!b || typeof b !== 'object' || Array.isArray(b) || Object.keys(b).sort().join(',') !== 'journal_commit,moteur,referentiel_version,set_id') throw new Error('corps : exactement { set_id, journal_commit, referentiel_version, moteur }');
if (typeof b.set_id !== 'string' || !SET_ID_PATTERN.test(b.set_id)) throw new Error('set_id invalide');
if (typeof b.journal_commit !== 'string' || !/^[0-9a-f]{40}$/.test(b.journal_commit)) throw new Error('journal_commit invalide');
if (typeof b.referentiel_version !== 'string' || !/^sha256:[0-9a-f]{64}$/.test(b.referentiel_version)) throw new Error('referentiel_version invalide');
const m = b.moteur;
if (!m || typeof m !== 'object' || typeof m.version !== 'string' || typeof m.sha256 !== 'string' || Object.keys(m).sort().join(',') !== 'sha256,version') throw new Error('moteur invalide');
return [{ json: { set_id: b.set_id, journal_commit: b.journal_commit, referentiel_version: b.referentiel_version, moteur: { version: m.version, sha256: m.sha256 } } }];

// FONDA — recherche du lot source : exactement un fichier, recherche paginée complète, avant lecture.
// GÉNÉRÉ par n8n/fonda-relecture-page/construire-relecture.js : ne pas éditer dans
// l'interface (le harnais compare ce code, octet pour octet, à celui du dépôt).

function unItem(nom) {
  const items = nom === null ? $input.all() : $(nom).all();
  if (!Array.isArray(items) || items.length !== 1 || !items[0] || typeof items[0].json !== 'object' || items[0].json === null) {
    throw new Error('Verifier recherche lot : exactement un item attendu de ' + (nom === null ? 'l\'entrée' : nom));
  }
  return items[0].json;
}

function agregerPages(nom) {
  const pages = $(nom).all().map((i) => i.json);
  if (!pages.length) throw new Error(nom + ' : aucune page');
  const fichiers = []; let incompleteSearch = false;
  for (const pg of pages) {
    if (!pg || !Array.isArray(pg.files)) throw new Error(nom + ' : page de listing inexploitable');
    if (pg.incompleteSearch === true) incompleteSearch = true;
    fichiers.push(...pg.files);
  }
  const plafond = Boolean(pages[pages.length - 1].nextPageToken);
  return { fichiers, incompleteSearch, plafond, complet: !incompleteSearch && !plafond };
}

const liste = agregerPages("Chercher lot source");
if (!liste.complet) throw new Error('recherche du lot source incomplète (incompleteSearch ou plafond de pagination)');
const fichiers = liste.fichiers;
if (fichiers.length !== 1 || typeof fichiers[0].id !== 'string') throw new Error(fichiers.length + ' fichier(s) pour du lot source : exactement un attendu');
return [{ json: { fichier_id: fichiers[0].id } }];

// FONDA — pré-conditions §21.5 : référentiel, moteur, réservation au journal, lot source complet ; candidat existant et decisions/ PROUVÉ vide.
// GÉNÉRÉ par n8n/fonda-relecture-page/construire-relecture.js : ne pas éditer dans
// l'interface (le harnais compare ce code, octet pour octet, à celui du dépôt).

function unItem(nom) {
  const items = nom === null ? $input.all() : $(nom).all();
  if (!Array.isArray(items) || items.length !== 1 || !items[0] || typeof items[0].json !== 'object' || items[0].json === null) {
    throw new Error('Analyser emission : exactement un item attendu de ' + (nom === null ? 'l\'entrée' : nom));
  }
  return items[0].json;
}

// SHA-256 (FIPS 180-4), UTF-8 et base64 en JavaScript pur.
function octetsUtf8(texte) {
  const o = [];
  for (let i = 0; i < texte.length; i += 1) {
    let c = texte.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < texte.length) {
      const d = texte.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i += 1; }
    }
    if (c >= 0xd800 && c <= 0xdfff) throw new Error('UTF-16 : substitut isolé');
    if (c < 0x80) o.push(c);
    else if (c < 0x800) o.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) o.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else o.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return o;
}
function sha256Hex(octets) {
